insert into policies(slug, title, body, version, status, effective_date, approved_by, requires_acceptance, published_at)
select 'integrity', 'سياسة النزاهة الأكاديمية', '## مقدمة
إن النزاهة الأكاديمية هي رمز أخلاقي يلتزم به المتدرب قائم على الأمانة التعليمية والصدق والسلوك القويم، بهدف تحقيق النجاح والتميز الأكاديمي.

وترتكز النزاهة الأكاديمية على الصدق، واحترام الجهود الفكرية للمركز وللآخرين، والابتعاد عن جميع مظاهر الغش والتزوير والانتحال أو أي فعل ينتهك هذا المبدأ.

## أهمية النزاهة الأكاديمية
- تعد النزاهة الأكاديمية أساس بناء مجتمع تعليمي سليم.
- تحدد مصداقية الأفراد في تعاملاتهم العلمية والعملية.
- تمثل مطلبًا أساسيًا داخل البيئة التدريبية للمعهد.
- تعزز قيم الصدق والأمانة بين المتدربين والمدربين والإداريين.

## أشكال انتهاك النزاهة الأكاديمية
- الغش بجميع أنواعه.
- السرقة الفكرية والانتحال الأدبي.
- تزوير أو تلفيق البيانات والتقارير أو التواقيع.
- انتحال شخصية الغير.
- بيع المحاضرات أو المذكرات أو الأبحاث دون إذن رسمي.
- أي ممارسات أخرى تخالف القيم الأكاديمية.

## الإجراءات المتبعة للحد من الانتهاكات
- الرصد الإلكتروني لمتابعة دخول المتدرب وتسجيل حضوره ونشاطه.
- متابعة التفاعل مع المحتوى والواجبات والأنشطة التعليمية.
- تسجيل الحضور والغياب في جميع المحاضرات المباشرة والأنشطة.
- تجاوز نسبة 25% غياب يؤدي إلى الحرمان من الشهادة.
- المسؤولية الفردية عن جميع الأعمال المقدمة من المتدرب.
- يمنع التعاون في المهام إلا بإذن خطي من المدرب.
- يمنع بيع أو مشاركة المواد التدريبية أو الأبحاث بدون إذن.
- يمنع التزوير أو تقديم بيانات غير صحيحة.

## الإجراءات التأديبية
- تتم المحافظة على سرية الحالات التأديبية.
- يتم إخطار المتدرب قبل اتخاذ أي إجراء.
- قد تشمل الإجراءات: الحرمان من الشهادة، أو الانسحاب من البرنامج، أو إجراءات إدارية أخرى.

## خلاصة
الالتزام بالنزاهة الأكاديمية هو أساس النجاح والتفوق، وهو انعكاس حقيقي لقيمة المتدرب وصدق مسيرته التعليمية.', 1, 'published', '2026-11-12', 'إدارة مركز سما القدرات للتدريب', true, now()
where not exists (select 1 from policies where slug = 'integrity');

insert into policies(slug, title, body, version, status, effective_date, approved_by, requires_acceptance, published_at)
select 'privacy', 'سياسة الخصوصية وحماية البيانات', 'يلتزم المركز بحماية خصوصية جميع المستفيدين والمحافظة على سرية البيانات والمعلومات الشخصية، وفق أعلى المعايير والأنظمة المعتمدة داخل المملكة العربية السعودية.

## إقرار
نحن نتعهد بضمان خصوصية المستفيدين والمحافظة على سرية جميع المعلومات المستلمة منهم، ويقتصر استخدامها على الجهات الحكومية المخوّل لها أو أحد فروعنا المعتمدة، لغرض إنجاز المعاملات أو تقديم الخدمات المتفق عليها مع المستفيدين.

## مقدمة
يدرك المركز أهمية حماية الخصوصية والبيانات الشخصية في العصر الرقمي، ويلتزم بحماية خصوصية مستخدمي خدماته أثناء التصفح أو استخدام الموقع الإلكتروني أو الالتحاق بالبرامج والدورات التدريبية.

## بيان سياسة الخصوصية
توضح هذه السياسة كيفية جمع البيانات، وأنواع البيانات التي يتم جمعها، وطرق حمايتها، وآلية مشاركتها مع الجهات ذات العلاقة، وتنطبق على الموقع وجميع الخدمات التابعة له.

## الشروط
- دخولك إلى الموقع يعني موافقتك على هذه الشروط وجميع الأنظمة ذات العلاقة.
- إذا لم توافق على الشروط، فلا يحق لك استخدام الموقع أو خدماته.
- جميع المواد المنشورة بالموقع محمية بموجب قوانين حقوق النشر والعلامات التجارية.

## لماذا نقوم بجمع ومعالجة بياناتك؟
- تسجيلك بالدورات التدريبية وإصدار الشهادات عبر منصة منار الإلكترونية.
- إرسال تنبيهات وتأكيدات التسجيل عبر البريد الإلكتروني أو الهاتف.
- تخصيص الخدمات وفق اهتماماتك وتزويدك بمحتوى مخصص.
- معالجة معاملات الدفع والامتثال للمتطلبات القانونية.
- حل المشكلات وتقديم العروض الترويجية والخصومات.

## الأساس القانوني لمعالجة البيانات
- موافقتك المسبقة عند التسجيل أو استخدام الخدمات.
- جمع البيانات عند إنشاء الحساب أو تعديل الملف الشخصي أو التواصل مع خدمة العملاء.

## من يمكنه الوصول إلى بياناتك؟
- موظفو المركز المصرح لهم وفق التزامات سرية صارمة.
- الموردون ومقدمو الخدمات المتعاقدون مع المركز.
- السلطات الرسمية عند الحاجة وفق الأنظمة.
- شركاء التدريب المعتمدون مع الالتزام بالسرية والأمان.

## حماية البيانات
- اعتماد إجراءات أمنية تقنية وتنظيمية لحماية البيانات.
- إلزام المستخدم بالحفاظ على سرية كلمة المرور وبيانات الدخول.
- إخطار المستخدمين فورًا عند حدوث أي خرق أمني وفق الأنظمة.

## مدة الاحتفاظ بالبيانات
- الاحتفاظ بالبيانات طالما الحساب نشط أو ما دامت هناك حاجة لذلك.
- تحويل البيانات لمجهولة أو حذفها عند عدم الحاجة.
- الاحتفاظ لفترات أطول عند وجود متطلبات قانونية.

## حقوق المستخدم
- الحق في الوصول إلى بياناتك الشخصية.
- الحق في تعديل البيانات غير الدقيقة أو تحديثها.
- الحق في سحب الموافقة على المعالجة في أي وقت.

## الكوكيز (Cookies)
- تُستخدم للتعرف عليك عند العودة للموقع أو حفظ تقدمك في الدورات.
- يمكن رفضها لكن ذلك قد يقلل من بعض مزايا الموقع.

## طرف ثالث
- قد يحتوي الموقع على روابط لمواقع أخرى غير خاضعة لهذه السياسة.
- ينصح بمراجعة سياسات الخصوصية الخاصة بتلك المواقع عند زيارتها.

## تحديثات سياسة الخصوصية
قد نقوم بتحديث هذه السياسة دوريًا استجابة للمتطلبات القانونية أو التشغيلية، وسيتم إخطار المستخدمين بأي تغييرات جوهرية.

## المحتوى المحظور
- محتوى يخالف العقيدة الإسلامية أو قوانين المملكة.
- محتوى تشهيري أو تهديدي أو غير لائق أو مخالف للملكية الفكرية.
- محتوى يتعلق بأنشطة سياسية حزبية أو غير مشروعة.
- فيروسات أو برمجيات ضارة.
- معلومات مضللة عمدًا.

ويحتفظ المركز بحق إنهاء استخدام الموقع في حال مخالفة هذه الشروط دون إشعار مسبق.', 1, 'published', '2026-11-12', 'إدارة مركز سما القدرات للتدريب', true, now()
where not exists (select 1 from policies where slug = 'privacy');

insert into policies(slug, title, body, version, status, effective_date, approved_by, requires_acceptance, published_at)
select 'attendance', 'سياسات الحضور والانضباط في الدورات التدريبية', 'حرصًا على تحقيق أعلى مستويات الجودة والانضباط في العملية التدريبية، تعتمد المنصة مجموعة من السياسات المنظمة لحضور المتدربين والتزامهم أثناء الدورات التدريبية.

## ضوابط الحضور والانضباط
- للحصول على شهادة حضور الدورة، يجب على المتدرب الالتزام بحضور ما لا يقل عن 75% من الساعات التدريبية.
- المشاركة عبر المنصة الإلكترونية تعادل الحضور الحضوري بشكل كامل.
- في البرامج التي تتجاوز مدتها شهرًا، يجب ألا تقل ساعات الحضور المتزامن عن 25%.
- يجب الدخول قبل بداية الدورة بـ 15 دقيقة والتأكد من الاتصال والصوت.
- يجب غلق الميكروفون أثناء الورشة وفتحه فقط عند المشاركة.
- مشاركة الكاميرا اختيارية، والمركز غير مسؤول عن أي ضرر ناتج عن استخدامها أثناء الدورة.
- يجب الاطلاع على الحقيبة التدريبية والملفات قبل بدء الدورة عبر موقع التسجيل.
- المركز غير مسؤول عن الأخطاء الناتجة عن سوء استخدام التقنية أثناء الحضور الإلكتروني.
- يمنع القيام بأي سلوك يضر بالمتدربين الآخرين أو ينتهك خصوصيتهم.
- يحظر تسجيل أو نشر محتوى الدورة أو المواد التدريبية لغير المشتركين، ويحق للمركز اتخاذ الإجراءات النظامية عند المخالفة.
- يجب إدخال البيانات الشخصية بشكل صحيح، وأي خطأ قد يحرم المتدرب من الشهادة ولا يمكن تعديلها بعد انتهاء الدورة.
- لا يحق استرجاع الرسوم بعد بدء الدورة، ويكون الاسترجاع متاحًا فقط قبل انطلاقها.
- عند غياب المتدرب، يسقط حقه في استرداد الرسوم إلا في حالة وجود عذر رسمي، وللمنصة حق قبول العذر أو رفضه.', 1, 'published', '2026-11-12', 'إدارة مركز سما القدرات للتدريب', true, now()
where not exists (select 1 from policies where slug = 'attendance');

insert into policies(slug, title, body, version, status, effective_date, approved_by, requires_acceptance, published_at)
select 'copyright', 'سياسة حقوق الملكية الفكرية وحقوق النشر', 'نلتزم بالامتثال الكامل لجميع أنظمة ولوائح حقوق الملكية الفكرية وحماية حقوق النشر المعمول بها في المملكة العربية السعودية، كما نؤكد حرصنا على حفظ حقوق جميع المستفيدين والمنسوبين للمنصة.

## إقرار
نتعهد نحن مركز سما القدرات للتدريب للتعليم والتدريب بالالتزام الكامل بجميع الأنظمة واللوائح ذات العلاقة بحقوق الملكية الفكرية وحقوق النشر، والعمل على حماية المحتوى التدريبي والتعليمي المقدم عبر المنصة.

## أولًا: حقوق الملكية الفكرية في بيئة التعلم الإلكتروني
- تمتلك المنصة حقوق استخدام المحتوى الإلكتروني المنشور عبر منصاتها الرسمية.
- تلتزم المنصة باحترام الملكية الفكرية عند تصميم وإعداد الدورات التدريبية والمحتوى التسويقي.
- يلتزم المدرب باستخدام محتوى المنصة لأغراضها فقط، ولا تتحمل المنصة مسؤولية أي استخدام خارجي.
- يجب على المدرب ذكر جميع المراجع والمصادر عند إعداد محتوى الدورة.
- في حال استخدام محتوى مفتوح المصدر، يجب الإشارة إلى المصدر بوضوح.
- يلتزم جميع المستخدمين بنظام حماية حقوق المؤلف السعودي.
- أي مخالفة تتعلق باستخدام محتوى غير مملوك للمنصة تقع مسؤوليتها على المدرب.
- جميع الدورات المرفوعة على المنصة تصبح حقًا للمنصة في الاستخدام والتطوير والتدريب.
- يلتزم المدرب والمتدرب بالحفاظ على سرية بيانات تسجيل الدخول وعدم مشاركتها مع الغير.

## ثانيًا: حقوق النشر في بيئة التعلم الإلكتروني
- يمنع نشر أي محتوى مسيء لأشخاص أو جهات.
- يمنع نشر أو اقتباس أي محتوى محمي بحقوق فكرية دون إذن رسمي.
- يمنع نشر أي محتوى مخالف لتعاليم الإسلام أو القيم المجتمعية.
- يمنع نشر أي محتوى يثير العنصرية أو الطائفية أو القبلية.
- يمنع الترويج لأي محتوى أو منتج تجاري داخل المنصة.

## ملاحظة هامة
أي خرق لهذه السياسات يعرض صاحبه للمساءلة القانونية وفق الأنظمة واللوائح المعتمدة لدى الهيئة السعودية للملكية الفكرية.', 1, 'published', '2026-11-12', 'إدارة مركز سما القدرات للتدريب', false, now()
where not exists (select 1 from policies where slug = 'copyright');

insert into policies(slug, title, body, version, status, effective_date, approved_by, requires_acceptance, published_at)
select 'support', 'سياسة الدعم الفني', 'نلتزم بتقديم الدعم الفني والتقني والأكاديمي لجميع المستفيدين من نظام التعليم الإلكتروني عبر القنوات الرسمية للمعهد، بما يضمن استمرارية العملية التدريبية بكفاءة وجودة عالية.

## الهدف
تقديم خدمات دعم متكاملة للمستفيدين من المنصة التدريبية، وضمان سرعة الاستجابة وحل المشكلات التقنية والأكاديمية بكفاءة.

## المستفيدون من الدعم
- المدربون المسجلون في المنصة.
- المتدربون المنضمون إلى الدورات التدريبية.
- الجهات الحكومية ذات العلاقة.

## آداب التواصل
- شرح المشكلة أو الاستفسار بوضوح.
- الالتزام بالاحترام وآداب الحوار.
- عدم استخدام أي عبارات مسيئة.
- الابتعاد عن النقاشات السياسية أو الدينية.

## خدمات الدعم الفني
- حل المشكلات التقنية المتعلقة بالمنصة.
- التدريب على استخدام النظام الإلكتروني.
- المساعدة في إنشاء الحسابات وتفعيلها.
- مساعدة المتدربين على استخراج الشهادات من منصة منار.

## قنوات الاتصال
أوقات العمل: من الأحد إلى الخميس – 9:00 صباحًا حتى 8:00 مساءً

كما يتوفر دعم إضافي أثناء انعقاد الدورات التدريبية المباشرة.

## التصعيد والمتابعة
في حال تأخر الرد، يتم التصعيد مباشرة إلى إدارة المنصة لضمان سرعة المعالجة واتخاذ الإجراءات اللازمة لمنع تكرار المشكلة.

## تقييم الخدمة
يتم قياس جودة خدمات الدعم الفني من خلال استبيان رضا المستفيدين بعد انتهاء الدورة التدريبية.', 1, 'published', '2026-11-12', 'إدارة مركز سما القدرات للتدريب', false, now()
where not exists (select 1 from policies where slug = 'support');

insert into policies(slug, title, body, version, status, effective_date, approved_by, requires_acceptance, published_at)
select 'communication', 'سياسات التواصل وآدابه', 'حرصًا على جودة التدريب وسلامته وضمان الاستفادة القصوى منه، وضع المعهد عددًا من الوسائل والسياسات التي تحقق ذلك، وهي كما يلي:

## قنوات التواصل
- الموقع الإلكتروني: يمكن من خلاله إيصال الاستفسارات أو الأفكار أو المقترحات أو حتى المشكلات.
- المحادثات المباشرة (الشات): متاحة مجانًا أثناء تقديم أي دورة مباشرة.
- حساب المركز (واتس): يستقبل تواصل المتدربين خلال ساعات العمل الرسمية.
- البريد الإلكتروني: مخصص للرد على الاستفسارات ومراسلات المتدربين.
- صفحة الدعم الفني: متاحة لحل كافة العقبات عبر الرابط المخصص.

## آداب التواصل
- الالتزام بالقيم الإسلامية والابتعاد عمّا يخالف الشريعة.
- احترام الأعراف والتقاليد الوطنية والابتعاد عن كل ما يخالفها.
- تجنب استخدام أي عبارات غير مناسبة أو ألفاظ خادشة للحياء.
- الالتزام بالآداب العامة وعدم إثارة النعرات أو التطرق إلى الطوائف المذهبية أو القبلية أو العرقية أو الانتقاص من الآخرين، فالاحترام واجب على الجميع.
- التأكد من الكتابة الصحيحة الخالية من الأخطاء.', 1, 'published', '2026-11-12', 'إدارة مركز سما القدرات للتدريب', false, now()
where not exists (select 1 from policies where slug = 'communication');

